import { readConfig } from '../utils/config.js';

export type AIStyle = 'conventional' | 'casual' | 'emoji';
type ChatMessage = { role: 'system' | 'user'; content: string };

const FALLBACK_PREFIX = '[AI unavailable]';

function sleep(ms: number) {
  return new Promise(res => setTimeout(res, ms));
}

async function callOpenAI(messages: ChatMessage[]) {
  const cfg = readConfig();
  const apiKey = process.env.OPENAI_API_KEY || cfg.tokens?.openai;
  const baseUrl = process.env.OPENAI_BASE_URL || cfg.aiBaseUrl || 'https://api.openai.com/v1';
  const model = cfg.aiModel || 'gpt-3.5-turbo';
  if (!apiKey) throw new Error('Missing OPENAI_API_KEY or config.tokens.openai');

  const res = await fetch(`${baseUrl}/chat/completions`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model,
      messages,
      temperature: 0.4,
      max_tokens: 200
    })
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`OpenAI error ${res.status}: ${errText}`);
  }
  const data = await res.json();
  const content = data.choices?.[0]?.message?.content?.trim();
  if (!content) throw new Error('Empty response from OpenAI');
  return content;
}

async function callProvider(messages: ChatMessage[]) {
  const cfg = readConfig();
  const provider = cfg.aiProvider || 'openai';
  if (provider === 'openai') return callOpenAI(messages);
  // Add other providers here; fallback to echo
  return messages.map(m => m.content).join('\n').slice(0, 200);
}

export async function generateAIResponse(prompt: string, style?: AIStyle): Promise<string> {
  const styleInstruction =
    style === 'conventional'
      ? 'Use Conventional Commits style.'
      : style === 'emoji'
      ? 'Lead with one relevant emoji.'
      : 'Use a concise, human tone.';

  const messages: ChatMessage[] = [
    { role: 'system', content: `${styleInstruction} Keep output under 120 characters when possible.` },
    { role: 'user', content: prompt }
  ];

  const attempts = 3;
  for (let i = 0; i < attempts; i++) {
    try {
      return await callProvider(messages);
    } catch (err) {
      if (i === attempts - 1) {
        return `${FALLBACK_PREFIX} ${style ? `[${style}] ` : ''}${prompt.slice(0, 120)}... (${err instanceof Error ? err.message : err})`;
      }
      await sleep(300 * (i + 1));
    }
  }
  return `${FALLBACK_PREFIX} ${prompt.slice(0, 120)}...`;
}
